def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    for dr,dc in [(1,1),(1,-1)]:
        runs=[]
        for r in range(h):
            for c in range(w):
                v=grid[r][c]
                if not v: continue
                pr,pc=r-dr,c-dc
                if 0<=pr<h and 0<=pc<w and grid[pr][pc]==v: continue
                cells=[]
                rr,cc=r,c
                while 0<=rr<h and 0<=cc<w and grid[rr][cc]==v:
                    cells.append((rr,cc));rr+=dr;cc+=dc
                if len(cells)>=4:
                    for a,b in cells: out[a][b]=v
    return out

